/**
 * Build the code-intel plugin artifacts into lib/.
 *
 * Three outputs:
 *  1. lib/index.js     — the Host plugin (Node ESM bundle, DSH peers external)
 *  2. lib/client.js    — the Web Client bundle, wrapped in the DSH browser
 *                        module-loader factory shape
 *  3. lib/types/**     — TypeScript declarations, emitted by tsc
 *
 * Everything @deepseek-ai/* stays an external require/import: the DSH Host and
 * browser module loaders resolve those from the profile. React, react-dom and
 * zod are also provided by the browser runtime and stay external in the client
 * bundle. `typescript` and `typescript-language-server` are never imported by
 * the bundle — the language server runs as a spawned subprocess, resolved by
 * path from this package's own node_modules at runtime.
 */
import { spawn } from 'node:child_process'
import { rm, mkdir, readFile, writeFile } from 'node:fs/promises'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const root = here
const lib = resolve(root, 'lib')
const CLIENT_PACKAGE = '@deepseek-ai/code-intel'

/** External modules resolved by the DSH Host plugin loader. */
const HOST_EXTERNALS = [
  /^@deepseek-ai\//,
  'zod',
]

/** External modules resolved by the DSH browser module loader. */
const CLIENT_EXTERNALS = [
  /^@deepseek-ai\/dsh-client-/,
  'react',
  'react-dom',
  'react/jsx-runtime',
  'react/jsx-dev-runtime',
  'zod',
]

function run(cmd, args, options = {}) {
  return new Promise((resolveP, rejectP) => {
    const child = spawn(cmd, args, { stdio: 'inherit', shell: process.platform === 'win32', ...options })
    child.on('error', rejectP)
    child.on('close', (code) => (code === 0 ? resolveP() : rejectP(new Error(`${cmd} exited with ${code}`))))
  })
}

/**
 * Wrap a CJS bundle in the DSH browser module-loader factory.
 *
 * The factory receives the platform's `require` for the externals; the bundle
 * body populates the `module`/`exports` pair we hand it, and we return
 * `module.exports` as the module's value, matching how shipped client bundles
 * are shaped.
 */
function wrapClientBundle(body, id) {
  return `/* Generated by build.mjs — do not edit. Web Client bundle of ${id}. */
window.__ModuleLoader__.load({
	id: ${JSON.stringify(id)},
	factory: (require) => {
		var module = { exports: {} };
		var exports = module.exports;
${body}
		return module.exports;
	}
});
`
}

async function buildHost() {
  console.log('• building Host bundle (lib/index.js)')
  await run('bun', [
    'build',
    resolve(root, 'src/index.ts'),
    '--format=esm',
    '--target=node',
    '--outfile=' + resolve(lib, 'index.js'),
    ...HOST_EXTERNALS.flatMap((pattern) => ['--external', typeof pattern === 'string' ? pattern : `/${pattern.source}/`]),
  ])
}

async function buildClient() {
  console.log('• building Web Client bundle (lib/client.js)')
  const staging = resolve(lib, '.client-stage.js')
  await run('bun', [
    'build',
    resolve(root, 'src/client/index.tsx'),
    '--format=cjs',
    '--target=browser',
    '--outfile=' + staging,
    '--sourcemap=none',
    ...CLIENT_EXTERNALS.flatMap((pattern) => ['--external', typeof pattern === 'string' ? pattern : `/${pattern.source}/`]),
  ])
  const body = await readFile(staging, 'utf8')
  // Drop any trailing sourceMappingURL directive; the wrapped bundle ships inline.
  const cleaned = body.replace(/\n?\/\/# sourceMappingURL=.*$/s, '')
  await writeFile(resolve(lib, 'client.js'), wrapClientBundle(cleaned, CLIENT_PACKAGE))
  await rm(staging)
}

async function buildTypes() {
  console.log('• building type declarations (lib/types)')
  await run('bunx', ['tsc', '--project', resolve(root, 'tsconfig.types.json')])
}

await rm(lib, { recursive: true, force: true })
await mkdir(lib, { recursive: true })
await buildHost()
await buildClient()
await buildTypes()
console.log('✓ build complete')
